// Shared, editable contact defaults supplied by the owner; public in the hosted source.
export const DEFAULT_SETTINGS={mapsProvider:'apple',restaurantPhone:'+12062575171',restaurant:'3247 California Ave SW, Seattle, WA 98116',mike:'+12062508612',cateringName:'Lawless Forge',cateringAddress:'45 S Spokane St, Seattle, WA 98134',rate:null,helpPhone:'+13602015208'};
export function applySettingsDefaults(state){let changed=false;for(const key of ['restaurant','mike','helpPhone','cateringName','cateringAddress','restaurantPhone','mapsProvider'])if(!String(state.settings[key]||'').trim()&&DEFAULT_SETTINGS[key]){state.settings[key]=DEFAULT_SETTINGS[key];changed=true;}if(!state.settings.contactDefaultsVersion){const phone=String(state.settings.mike||'').replace(/\D/g,'').replace(/^1(?=\d{10}$)/,'');if(phone==='3602015208'){state.settings.mike=DEFAULT_SETTINGS.mike;changed=true;}state.settings.contactDefaultsVersion=1;changed=true;}if(state.settings.restaurant==='Sample restaurant, Seattle, WA'){state.settings.restaurant=DEFAULT_SETTINGS.restaurant;changed=true;}return changed;}

export function cateringDefaults(settings={}){return {isCatering:true,name:String(settings.cateringName||DEFAULT_SETTINGS.cateringName),address:String(settings.cateringAddress||DEFAULT_SETTINGS.cateringAddress),phone:''};}
